class LibraryMember{private int borrowed;LibraryMember(String i,int l){}void borrowBook(){borrowed++;}int getBooksBorrowed(){return borrowed;}String displayInfo(){return "General Member | Books Borrowed: "+borrowed;}}
class StudentMember extends LibraryMember{String course;StudentMember(String i,int l,String c){super(i,l);course=c;}String displayInfo(){return "Student Member | Course: "+course+" | Books Borrowed: "+getBooksBorrowed();}}
class HonorsStudentMember extends StudentMember{int bonusLimit;HonorsStudentMember(String i,int l,String c,int b){super(i,l,c);bonusLimit=b;}String displayInfo(){return "Honors Student Member | Course: "+course+" | Bonus Limit: "+bonusLimit+" | Books Borrowed: "+getBooksBorrowed();}}
class FacultyMember extends LibraryMember{String department;FacultyMember(String i,int l,String d){super(i,l);department=d;}String displayInfo(){return "Faculty Member | Department: "+department+" | Books Borrowed: "+getBooksBorrowed();}}
public class Main{static String classifyGeneration(LibraryMember m){if(m instanceof HonorsStudentMember)return "Multilevel descendant (3 generations deep)";if(m instanceof FacultyMember)return "Hierarchical sibling (independent branch)";return "General member";}static int getTotalBooksBorrowed(LibraryMember[] ms){int s=0;for(LibraryMember m:ms)s+=m.getBooksBorrowed();return s;}public static void main(String[]a){}}